import React from "react";
import {
  FaClone,
  FaUserCog,
  FaUserEdit,
  FaPhoneAlt,
  FaPhone,
  FaMapMarkerAlt,
  FaImage,
  FaMicrochip,
  FaTag,
  FaQuestionCircle,
  FaClock,
  FaSyncAlt,
  FaFileAlt,
  FaCoins,
  FaBoxOpen,
  FaFileInvoice,
  FaExclamationCircle,
  FaChevronLeft,
  FaCommentDots,
} from "react-icons/fa";
import InfoField from "./InfoFieldComponenet";
import withRouter from "./withRouter";
import AuthCheck from "./AuthCheckComponent";

const API_URL = "https://iranaserviceapp.ir/test/api";

class RequestDetailPage extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      request: null,
      clear: null,
      loading: true,
      authenticated: false,
    };

    this.handleBack = this.handleBack.bind(this);
    this.handleChat = this.handleChat.bind(this);
    this.handleAddRelated = this.handleAddRelated.bind(this);
  }

  componentDidMount() {
    if (!AuthCheck()) {
      return;
    }

    this.setState(
      {
        authenticated: true,
      },
      () => {
        this.getRequestDetail();
      }
    );
  }

  getRequestDetail() {
    const { id } = this.props.params;
    const token = localStorage.getItem("token");

    fetch(`${API_URL}/detail?id=${id}`, {
      method: "GET",
      headers: {
        Accept: "application/json",
        Authorization: `Bearer ${token}`,
      },
    })
      .then((response) => response.json())
      .then((data) => {
        console.log("REQUEST DETAIL API:", data);

        this.setState({
          request: data.request || null,
          clear: data.clear || null,
          loading: false,
        });
      })
      .catch((error) => {
        console.error("GET REQUEST DETAIL ERROR:", error);

        this.setState({
          request: null,
          clear: null,
          loading: false,
        });
      });
  }

  handleBack() {
    this.props.navigate(-1);
  }

  handleChat() {
    console.log("رفتن به گفتگو");
  }

  handleAddRelated() {
    console.log("افزودن درخواست مرتبط");
  }

  formatNumber(value) {
    if (value === null || value === undefined || value === "") {
      return "---";
    }

    const number = Number(value);

    if (Number.isNaN(number)) {
      return value;
    }

    return number.toLocaleString("fa-IR");
  }

  render() {
    if (!this.state.authenticated) {
      return null;
    }

    const {
      request,
      clear,
      loading,
    } = this.state;

    if (loading) {
      return (
        <div className="text-center text-muted py-5">
          در حال دریافت اطلاعات...
        </div>
      );
    }

    if (!request) {
      return (
        <div className="text-center text-muted py-5">
          اطلاعات درخواست پیدا نشد.
        </div>
      );
    }

    /*
     * ============================
     * اطلاعات اصلی درخواست
     * ============================
     */

    const requestNumber = request.code || request.id || "---";

    const technicianName =
      request.repairman_model
        ? `${request.repairman_model.name || ""} ${
            request.repairman_model.family || ""
          }`.trim()
        : "---";

    /*
     * نام مشتری
     *
     * بسته به ساختار API ممکن است customer یا name باشد.
     */
    const customerName =
      request.customer?.name ||
      request.customer_name ||
      request.name ||
      "---";

    /*
     * شماره تماس
     */
    const phone =
      request.customer?.mobile ||
      request.mobile ||
      request.phone ||
      "---";

    /*
     * تلفن ثابت
     */
    const landline =
      request.landline ||
      request.phone2 ||
      "---";

    /*
     * استان
     */
    const province =
      request.state_model?.name ||
      request.state_name ||
      "---";

    /*
     * آدرس
     */
    const address =
      request.address ||
      "---";

    /*
     * نوع دستگاه
     */
    const deviceType =
      request.device_type ||
      request.type ||
      "---";

    /*
     * برند
     */
    const deviceBrand =
      request.brand ||
      request.brand_name ||
      "---";

    /*
     * ایراد دستگاه
     */
    const deviceIssue =
      request.problem ||
      request.issue ||
      request.description ||
      "---";

    /*
     * زمان مراجعه
     */
    const visitTime =
      request.time ||
      request.visit_time ||
      "---";

    /*
     * توضیحات درخواست
     */
    const description =
      request.description ||
      request.desc ||
      "---";

    /*
     * =========================================
     * اطلاعات CLEAR
     * =========================================
     *
     * اگر clear وجود نداشته باشد همه این مقادیر ---
     * خواهند بود.
     */

    const hasClear = clear !== null && clear !== undefined;

    /*
     * وضعیت
     */
    const status = hasClear
      ? "تسویه شده"
      : "منتظر تایید تعمیرکار";

    /*
     * کل دریافتی
     *
     * اگر در clear فیلد مربوطه وجود داشته باشد
     * استفاده می‌شود.
     */
    const totalReceived = hasClear
      ? this.formatNumber(
          clear.total_received ??
            clear.total ??
            clear.received ??
            clear.sum
        )
      : "---";

    /*
     * هزینه لوازم مصرفی
     */
    const suppliesCost = hasClear
      ? this.formatNumber(
          clear.supplies_cost ??
            clear.cost ??
            clear.material_cost
        )
      : "---";

    /*
     * لوازم مصرفی
     */
    const suppliesUsed = hasClear
      ? clear.supplies_used ??
        clear.supplies ??
        clear.materials ??
        "---"
      : "---";

    /*
     * کل اجرت
     */
    const totalFee = hasClear
      ? this.formatNumber(
          clear.total_fee ??
            clear.fee ??
            clear.wage
        )
      : "---";

    /*
     * درصد پورسانت
     */
    const commissionPercent = hasClear
      ? clear.commission_percent ??
        clear.percent ??
        clear.percentage ??
        "---"
      : "---";

    /*
     * مبلغ پورسانت
     */
    const commissionAmount = hasClear
      ? this.formatNumber(
          clear.commission_amount ??
            clear.commission ??
            clear.commission_total
        )
      : "---";

    /*
     * توضیحات تایید تسویه
     */
    const settlementNote = hasClear
      ? clear.description ||
        clear.desc ||
        clear.text1 ||
        "---"
      : "---";

    /*
     * فیش واریزی
     *
     * اول clear.file1 و بعد file1 خود request
     */
    const receiptFile =
      clear?.file1 ||
      request.file1 ||
      null;

    const receiptImage = receiptFile
      ? `https://iranaserviceapp.ir/test/files/clear/${receiptFile}`
      : null;

    /*
     * درخواست‌های مرتبط
     */
    const relatedRequests = Array.isArray(request.siblings)
      ? request.siblings
      : [];

    return (
      <div dir="rtl">
        <div className="container px-3 pt-4 pb-5">

          {/* هدر */}
          <div className="d-flex align-items-center justify-content-between mb-4">

            <button
              type="button"
              onClick={this.handleBack}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaChevronLeft size={14} />
            </button>

            <button
              type="button"
              onClick={this.handleChat}
              className="btn btn-light rounded-circle p-2 d-flex align-items-center justify-content-center text-danger"
              style={{
                width: 36,
                height: 36,
              }}
            >
              <FaCommentDots size={16} />
            </button>

          </div>

          {/* شماره درخواست */}
          <InfoField
            icon={<FaClone size={18} />}
            label="شماره درخواست"
            value={requestNumber}
          />

          {/* نام تعمیرکار */}
          <InfoField
            icon={<FaUserCog size={18} />}
            label="نام تعمیرکار"
            value={technicianName}
          />

          {/* نام مشتری */}
          <InfoField
            icon={<FaUserEdit size={18} />}
            label="نام مشتری"
            value={customerName}
          />

          {/* شماره تماس */}
          <InfoField
            icon={<FaPhoneAlt size={18} />}
            label="شماره تماس"
            value={phone}
          />

          {/* تلفن ثابت */}
          <InfoField
            icon={<FaPhone size={18} />}
            label="تلفن ثابت"
            value={landline}
          />

          {/* استان */}
          <InfoField
            icon={<FaMapMarkerAlt size={18} />}
            label="استان"
            value={province}
          />

          {/* آدرس */}
          <InfoField
            icon={<FaImage size={18} />}
            label="آدرس"
            value={address}
          />

          {/* نوع دستگاه */}
          <InfoField
            icon={<FaMicrochip size={18} />}
            label="نوع دستگاه"
            value={deviceType}
          />

          {/* برند دستگاه */}
          <InfoField
            icon={<FaTag size={18} />}
            label="برند دستگاه"
            value={deviceBrand}
          />

          {/* ایراد دستگاه */}
          <InfoField
            icon={<FaQuestionCircle size={18} />}
            label="ایراد دستگاه"
            value={deviceIssue}
          />

          {/* زمان مراجعه */}
          <InfoField
            icon={<FaClock size={18} />}
            label="زمان مراجعه"
            value={visitTime}
          />

          {/* توضیحات */}
          <InfoField
            icon={<FaSyncAlt size={18} />}
            label="توضیحات"
            value={description}
          />

          {/* وضعیت */}
          <InfoField
            icon={<FaFileAlt size={18} />}
            label="وضعیت"
          >
            <span
              className={
                hasClear
                  ? "text-success fw-semibold"
                  : "text-warning fw-semibold"
              }
            >
              {status}
            </span>
          </InfoField>

          {/* ========================= */}
          {/* اطلاعات مالی CLEAR */}
          {/* ========================= */}

          {/* کل دریافتی */}
          <InfoField
            icon={<FaCoins size={18} />}
            label="کل دریافتی"
          >
            <span className="fw-semibold">
              {totalReceived}
              {totalReceived !== "---" && " تومان"}
            </span>
          </InfoField>

          {/* هزینه لوازم مصرفی */}
          <InfoField
            icon={<FaCoins size={18} />}
            label="هزینه لوازم مصرفی"
          >
            <span className="fw-semibold">
              {suppliesCost}
              {suppliesCost !== "---" && " تومان"}
            </span>
          </InfoField>

          {/* لوازم مصرفی */}
          <InfoField
            icon={<FaBoxOpen size={18} />}
            label="لوازم مصرفی"
            value={suppliesUsed}
          />

          {/* کل اجرت */}
          <InfoField
            icon={<FaFileInvoice size={18} />}
            label="کل اجرت"
          >
            <span className="fw-semibold">
              {totalFee}
              {totalFee !== "---" && " تومان"}
            </span>
          </InfoField>

          {/* پورسانت */}
          <InfoField
            icon={<FaFileInvoice size={18} />}
            label={
              commissionPercent === "---"
                ? "پورسانت"
                : `پورسانت (%${commissionPercent})`
            }
          >
            <span className="fw-semibold">
              {commissionAmount}
              {commissionAmount !== "---" && " تومان"}
            </span>
          </InfoField>

          {/* ========================= */}
          {/* فیش واریزی */}
          {/* ========================= */}

          {receiptImage && (
            <div className="d-flex align-items-center justify-content-between gap-3 border rounded-4 px-3 py-3 mb-3 bg-white">

              <span className="text-muted">
                فیش واریزی:
              </span>

              <img
                src={receiptImage}
                alt="فیش واریزی"
                className="rounded-3 border"
                style={{
                  width: 140,
                  height: 110,
                  objectFit: "cover",
                  cursor: "pointer",
                }}
                onClick={() => window.open(receiptImage, "_blank")}
              />

            </div>
          )}

          {/* توضیحات تایید تسویه */}
          <InfoField
            icon={<FaExclamationCircle size={18} />}
            label="توضیحات تایید تسویه"
            value={settlementNote}
          />

          {/* درخواست‌های مرتبط */}
          <h2 className="fs-6 fw-semibold text-dark mt-4 mb-3 text-end">
            درخواست‌های مرتبط:
          </h2>

          {relatedRequests.length === 0 ? (
            <div className="text-center text-muted py-4">
              هنوز موردی برای نمایش وجود ندارد.
            </div>
          ) : (
            <div>
              {relatedRequests.map((rel) => (
                <div
                  key={rel.id}
                  className="border rounded-3 p-3 mb-2 text-end bg-white"
                >
                  {rel.code || rel.id}
                </div>
              ))}
            </div>
          )}

          {/* افزودن درخواست مرتبط */}
          <button
            type="button"
            onClick={this.handleAddRelated}
            className="btn btn-primary w-100 rounded-3 py-3 mt-2"
            style={{
              transition: "opacity 0.15s ease",
            }}
          >
            افزودن درخواست مرتبط
          </button>

        </div>
      </div>
    );
  }
}

export default withRouter(RequestDetailPage);
